style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
html, body, ytd-app, #page-manager, #content {
    background: none !important;
    background-color: transparent !important;
  }

  ytd-app::before {
    content: "";
    background-image: url("https://wallpapercrafter.com/desktop2/763738-anime-anime-girls-Oyuyu-Hololive-Mori-Calliope.jpg");
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center center;
    background-attachment: fixed;
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: -1;
    opacity: 1; /* You can change this for visibility */
  }
}
